import{_ as o,o as i,c as a,ae as n}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Protocol Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/20260226-helios-market-research/08_PROTOCOL_DECISIONS.md","filePath":"sessions/20260226-helios-market-research/08_PROTOCOL_DECISIONS.md"}'),t={name:"sessions/20260226-helios-market-research/08_PROTOCOL_DECISIONS.md"};function l(s,e,r,c,d,u){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="protocol-decisions" tabindex="-1">Protocol Decisions <a class="header-anchor" href="#protocol-decisions" aria-label="Permalink to &quot;Protocol Decisions&quot;">​</a></h1><p>Date: 2026-02-26 Status: Accepted</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Lock protocol usage and naming to avoid ACP ambiguity.</p><h2 id="decision-1-acp-meaning-in-helios" tabindex="-1">Decision 1: ACP meaning in Helios <a class="header-anchor" href="#decision-1-acp-meaning-in-helios" aria-label="Permalink to &quot;Decision 1: ACP meaning in Helios&quot;">​</a></h2><p>Helios uses <code>ACP</code> to mean <strong>Agent Client Protocol</strong> at the app-client boundary.</p><ul><li>Helios acts as the client/editor.</li><li>ACP is used for client-to-agent runtime wiring where ACP-compatible adapters are available.</li></ul><p>Helios does <strong>not</strong> use ACP as a replacement for internal runtime orchestration.</p><h2 id="decision-2-internal-runtime-control" tabindex="-1">Decision 2: Internal runtime control <a class="header-anchor" href="#decision-2-internal-runtime-control" aria-label="Permalink to &quot;Decision 2: Internal runtime control&quot;">​</a></h2><p>Use <code>helios.localbus.v1</code> (internal local control bus) as source of truth for:</p><ul><li>session lifecycle</li><li>terminal lifecycle</li><li>renderer switching</li><li>approvals and policy events</li><li>audit correlation</li></ul><h2 id="decision-3-mcp-usage" tabindex="-1">Decision 3: MCP usage <a class="header-anchor" href="#decision-3-mcp-usage" aria-label="Permalink to &quot;Decision 3: MCP usage&quot;">​</a></h2><p>Use <code>MCP</code> for tool/resource interoperability only.</p><ul><li>MCP calls are initiated by runtime services.</li><li>MCP events map into local bus audit and progress events.</li></ul><h2 id="decision-4-a2a-usage" tabindex="-1">Decision 4: A2A usage <a class="header-anchor" href="#decision-4-a2a-usage" aria-label="Permalink to &quot;Decision 4: A2A usage&quot;">​</a></h2><p>Use <code>A2A</code> only at external federation boundaries.</p><ul><li>no A2A dependency for local single-user execution</li><li>external agent delegations must map back to local <code>agent.run.*</code> lifecycle</li></ul><h2 id="decision-5-ag-ui-usage" tabindex="-1">Decision 5: AG-UI usage <a class="header-anchor" href="#decision-5-ag-ui-usage" aria-label="Permalink to &quot;Decision 5: AG-UI usage&quot;">​</a></h2><p>Use AG-UI as optional frontend event contract adapter.</p><ul><li>local bus remains canonical</li><li>AG-UI is projection/translation for UI composition</li></ul><h2 id="decision-6-protocol-precedence" tabindex="-1">Decision 6: Protocol precedence <a class="header-anchor" href="#decision-6-protocol-precedence" aria-label="Permalink to &quot;Decision 6: Protocol precedence&quot;">​</a></h2><p>When multiple transports/protocols overlap:</p><ol><li>internal local bus semantics are authoritative</li><li>ACP/MCP/A2A/AG-UI adapters must preserve local event truth</li><li>adapters cannot mutate semantic meaning of command outcomes</li></ol>',23)])])}const m=o(t,[["render",l]]);export{h as __pageData,m as default};
